// Multi-Agent Chat with Initial Greeting Support
const { ChatOpenAI } = require('@langchain/openai');
const { HumanMessage, AIMessage, SystemMessage } = require('@langchain/core/messages');

// Get input data
const inputData = $input.first().json.body;
const { expedition, chatHistory, message } = inputData;
const agents = expedition.agents || [];

// Get OpenAI API key
const OPENAI_API_KEY = $env.OPENAI_API_KEY || 'sk-YOUR-API-KEY';

if (!OPENAI_API_KEY || OPENAI_API_KEY === 'sk-YOUR-API-KEY') {
  return [{
    json: {
      message: "Please configure your OpenAI API key in the workflow.",
      agentReady: false,
      missionStatus: 'error',
      workflowId: $workflow.id
    }
  }];
}

if (agents.length === 0) {
  return [{
    json: {
      message: "⚠️ No agents assigned to this expedition.",
      agentReady: false,
      missionStatus: 'no_agents',
      shouldTerminateChat: true,
      workflowId: $workflow.id
    }
  }];
}

// Initialize LLM
const llm = new ChatOpenAI({
  apiKey: OPENAI_API_KEY,
  model: 'gpt-4-turbo-preview',
  temperature: 0.7
});

// Check if this is an initial greeting request
const isInitialGreeting = message === "[SYSTEM_INITIAL_GREETING]";

// Check conversation state
let isAgentReady = chatHistory?.some(msg => 
  msg.role === 'assistant' && 
  msg.content.toLowerCase().includes('i am ready to execute the mission')
) || false;

const userWantsToExecute = !isInitialGreeting && message.toLowerCase().match(/\b(execute|start|begin|launch|go)\b/);

if (isAgentReady && userWantsToExecute) {
  return [{
    json: {
      message: `🚀 MISSION EXECUTION INITIATED!\n\nAll systems are go! The expedition is now underway.`,
      agentReady: true,
      missionStatus: 'executing',
      isExecuting: true,
      shouldTerminateChat: true,
      workflowId: $workflow.id
    }
  }];
}

// Select appropriate agent
let selectedAgent = agents[0];

if (!isInitialGreeting) {
  // Normal message - route based on content
  const msgLower = message.toLowerCase();
  for (const agent of agents) {
    const agentKeywords = agent.description.toLowerCase().split(' ');
    if (agentKeywords.some(keyword => msgLower.includes(keyword))) {
      selectedAgent = agent;
      break;
    }
  }
} else {
  // For initial greeting, select the agent most relevant to the expedition
  const expeditionKeywords = expedition.description.toLowerCase().split(' ');
  for (const agent of agents) {
    const agentKeywords = agent.description.toLowerCase().split(' ');
    if (agentKeywords.some(keyword => expeditionKeywords.includes(keyword))) {
      selectedAgent = agent;
      break;
    }
  }
}

// Create agent prompt
let agentPrompt;
if (isInitialGreeting) {
  // Special prompt for initial greeting
  agentPrompt = `You are ${selectedAgent.name}, specializing in ${selectedAgent.description}.

You're part of an expedition: ${expedition.name} - ${expedition.description}.

Your team includes:
${agents.map(a => `- ${a.name}: ${a.description}`).join('\n')}

This is the start of a new expedition conversation. Generate a SHORT, warm greeting that:
1. Briefly introduce yourself (one sentence)
2. Ask ONE specific, focused question related to your expertise to get started

Keep it simple, conversational, and under 3 sentences total. Don't overwhelm with information.

IMPORTANT: Do NOT add any signature or name at the end of your message. Your name is already shown in the chat interface.`;
} else {
  // Normal conversation prompt
  agentPrompt = `You are ${selectedAgent.name}, specializing in ${selectedAgent.description}.

Expedition: ${expedition.name} - ${expedition.description}

Your team includes:
${agents.map(a => `- ${a.name}: ${a.description}`).join('\n')}

Instructions:
1. Focus on your expertise area
2. Ask 2-3 specific questions if needed
3. Be concise and professional
4. If the topic is outside your expertise, say: "For [topic], [agent name] would be better suited to help."
5. When ready, say: "I am ready to execute the mission."`;
}

// Build conversation
const messages = [new SystemMessage(agentPrompt)];

if (!isInitialGreeting && chatHistory) {
  chatHistory.forEach(msg => {
    messages.push(msg.role === 'user' ? new HumanMessage(msg.content) : new AIMessage(msg.content));
  });
  messages.push(new HumanMessage(message));
} else if (isInitialGreeting) {
  // For initial greeting, just ask for a greeting
  messages.push(new HumanMessage("Please provide your initial greeting and questions."));
}

// Get response
try {
  const response = await llm.invoke(messages);
  const responseContent = response.content;

  // Check if declaring ready (not for initial greeting)
  const declaringReady = !isInitialGreeting && responseContent.toLowerCase().includes('i am ready to execute the mission');

  return [{
    json: {
      message: `[${selectedAgent.name}]: ${responseContent}`,
      agentReady: declaringReady || isAgentReady,
      missionStatus: declaringReady || isAgentReady ? 'ready_to_execute' : 'gathering_requirements',
      isExecuting: false,
      shouldTerminateChat: false,
      workflowId: $workflow.id,
      timestamp: new Date().toISOString(),
      metadata: {
        respondingAgent: selectedAgent.name,
        isInitialGreeting: isInitialGreeting
      }
    }
  }];
} catch (error) {
  return [{
    json: {
      message: `[${selectedAgent.name}]: I apologize, but I encountered an error. Please try again.`,
      agentReady: false,
      missionStatus: 'error',
      workflowId: $workflow.id,
      error: error.message
    }
  }];
}
